package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.ObjectMapper;import java.util.*;import static com.greatleyposhley.professy.collaboration.WorkAccess.number;
/** Versioned, private-by-default Sheets and Slides. All gateways enforce the same canonical ACL. */
@RestController @RequestMapping("/api/workspace/files/{kind}")public class WorkspaceFiles {
 private final WorkAccess access;private final ObjectMapper json;public WorkspaceFiles(WorkAccess access,ObjectMapper json){this.access=access;this.json=json;}
 private String kind(String value){String k=value.toUpperCase(Locale.ROOT);if(!Set.of("SHEETS","SLIDES").contains(k))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return k;}
 private String text(Object value,int max){String s=Objects.toString(value,"").trim();if(s.length()>max)throw new IllegalArgumentException("Field exceeds its size limit");return s;}
 private Map<String,Object> row(String kind,long id,boolean edit){access.require(kind(kind)+(edit?".UPDATE":".READ"));var user=access.actor();var rows=access.jdbc.queryForList("SELECT f.*,COALESCE(s.permission,'') AS permission FROM workspace_files f LEFT JOIN workspace_file_shares s ON s.file_id=f.id AND s.user_id=? WHERE f.id=? AND f.org_id=? AND f.file_type=? AND (f.owner_id=? OR s.user_id=?)",user.getId(),id,user.getOrgId(),kind(kind),user.getId(),user.getId());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"File not found or not shared with you");var row=rows.getFirst();if(edit&&number(row.get("owner_id"))!=user.getId()&&!"EDITOR".equals(row.get("permission")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You have read-only access");return row;}
 private boolean owner(Map<String,Object> row){return number(row.get("owner_id"))==access.actor().getId();}
 private Map<String,Object> view(Map<String,Object> row,boolean content){var v=new LinkedHashMap<String,Object>();v.put("id",row.get("id"));v.put("title",row.get("title"));v.put("revision",row.get("revision"));v.put("ownerId",row.get("owner_id"));v.put("updatedAt",row.get("updated_at"));v.put("createdAt",row.get("created_at"));v.put("canShare",owner(row));v.put("canEdit",access.policy.can(access.actor(),row.get("file_type")+".UPDATE")&&(owner(row)||"EDITOR".equals(row.get("permission"))));v.put("tags",json.readValue(row.get("tags_json").toString(),List.class));var names=access.jdbc.queryForList("SELECT CONCAT_WS(' ',first_name,last_name) AS name FROM user_account WHERE id=? AND org_id=?",String.class,row.get("owner_id"),access.actor().getOrgId());v.put("ownerName",names.isEmpty()?"Former member":names.getFirst());if(content)v.put("content",json.readValue(row.get("content_json").toString(),Map.class));return v;}
 @GetMapping public Object list(@PathVariable String kind,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int offset){access.require(kind(kind)+".READ");var user=access.actor();int start=Math.max(0,offset);String term="%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%";var rows=access.jdbc.queryForList("SELECT f.*,COALESCE(s.permission,'') AS permission FROM workspace_files f LEFT JOIN workspace_file_shares s ON s.file_id=f.id AND s.user_id=? WHERE f.org_id=? AND f.file_type=? AND (f.owner_id=? OR s.user_id=?) AND f.title LIKE ? ESCAPE '!' ORDER BY f.updated_at DESC,f.id DESC LIMIT 25 OFFSET ?",user.getId(),user.getOrgId(),kind(kind),user.getId(),user.getId(),term,start);boolean more=rows.size()>24;return Map.of("items",rows.subList(0,Math.min(24,rows.size())).stream().map(r->view(r,false)).toList(),"nextOffset",more?start+24:-1);}
 @GetMapping("/{id}")public Object get(@PathVariable String kind,@PathVariable long id){return view(row(kind,id,false),true);}
 private String title(Map<String,Object> body){String title=text(body.get("title"),255);if(title.isBlank())throw new IllegalArgumentException("Title is required");return title;}
 private String content(Map<String,Object> body){if(!(body.get("content") instanceof Map))throw new IllegalArgumentException("File content is required");return text(json.writeValueAsString(body.get("content")),1500000);}
 private String tags(Map<String,Object> body){var values=body.get("tags") instanceof List<?> list?list:List.of();if(values.size()>20)throw new IllegalArgumentException("Use up to 20 tags");return json.writeValueAsString(values.stream().map(v->text(v,50).toLowerCase(Locale.ROOT)).filter(v->!v.isBlank()).distinct().toList());}
 @PostMapping @Transactional public Object create(@PathVariable String kind,@RequestBody Map<String,Object> body){access.require(kind(kind)+".CREATE");var u=access.actor();String t=title(body),c=content(body);access.jdbc.update("INSERT INTO workspace_files(org_id,file_type,title,owner_id,content_json,tags_json) VALUES(?,?,?,?,?,?)",u.getOrgId(),kind(kind),t,u.getId(),c,tags(body));long id=access.jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);snapshot(id,1,t,c);access.policy.event(u,"FILE_UPDATED",0);return get(kind,id);}
 @PutMapping("/{id}")@Transactional public Object save(@PathVariable String kind,@PathVariable long id,@RequestBody Map<String,Object> body){row(kind,id,true);String t=title(body),c=content(body);long rev=number(body.get("revision"));int count=access.jdbc.update("UPDATE workspace_files SET title=?,content_json=?,tags_json=?,revision=revision+1 WHERE id=? AND revision=?",t,c,tags(body),id,rev);if(count!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"This file changed in another tab. Save a copy or reload before saving.");snapshot(id,rev+1,t,c);access.policy.event(access.actor(),"FILE_UPDATED",0);return get(kind,id);}
 private void snapshot(long id,long revision,String title,String content){access.jdbc.update("INSERT INTO workspace_file_versions(file_id,revision,title,content_json,saved_by) VALUES(?,?,?,?,?)",id,revision,title,content,access.actor().getId());}
 @DeleteMapping("/{id}")@Transactional public void delete(@PathVariable String kind,@PathVariable long id){if(!owner(row(kind,id,false)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the owner can delete this file");access.jdbc.update("DELETE FROM workspace_files WHERE id=?",id);access.policy.event(access.actor(),"FILE_UPDATED",0);}
 @GetMapping("/{id}/versions")public Object versions(@PathVariable String kind,@PathVariable long id){row(kind,id,false);return access.jdbc.queryForList("SELECT revision,title,created_at AS createdAt FROM workspace_file_versions WHERE file_id=? ORDER BY revision DESC LIMIT 100",id);}
 @GetMapping("/{id}/versions/{revision}")public Object version(@PathVariable String kind,@PathVariable long id,@PathVariable long revision){row(kind,id,false);var rows=access.jdbc.queryForList("SELECT title,content_json FROM workspace_file_versions WHERE file_id=? AND revision=?",id,revision);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return Map.of("title",rows.getFirst().get("title"),"content",json.readValue(rows.getFirst().get("content_json").toString(),Map.class));}
 @GetMapping("/{id}/sharing")public Object sharing(@PathVariable String kind,@PathVariable long id){if(!owner(row(kind,id,false)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return access.jdbc.queryForList("SELECT s.user_id AS userId,s.permission,CONCAT_WS(' ',u.first_name,u.last_name) AS name,u.email FROM workspace_file_shares s JOIN user_account u ON u.id=s.user_id WHERE s.file_id=? ORDER BY u.first_name",id);}
 @PutMapping("/{id}/sharing")@Transactional public Object share(@PathVariable String kind,@PathVariable long id,@RequestBody List<Map<String,Object>> shares){if(!owner(row(kind,id,false)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(shares.size()>200)throw new IllegalArgumentException("Choose up to 200 people");for(var share:shares){if(!Set.of("VIEWER","EDITOR").contains(share.get("permission"))||access.jdbc.queryForObject("SELECT COUNT(*) FROM user_account WHERE id=? AND org_id=? AND is_active=1",Integer.class,number(share.get("userId")),access.actor().getOrgId())!=1)throw new IllegalArgumentException("Select an active person and permission");}access.jdbc.update("DELETE FROM workspace_file_shares WHERE file_id=?",id);for(var share:shares)access.jdbc.update("INSERT INTO workspace_file_shares(file_id,user_id,permission) VALUES(?,?,?)",id,share.get("userId"),share.get("permission"));return sharing(kind,id);}
 @GetMapping("/{id}/comments")public Object comments(@PathVariable String kind,@PathVariable long id){row(kind,id,false);return access.jdbc.queryForList("SELECT c.id,c.content,c.created_at AS createdAt,CONCAT_WS(' ',u.first_name,u.last_name) AS authorName FROM workspace_file_comments c JOIN user_account u ON u.id=c.user_id WHERE c.file_id=? ORDER BY c.id",id);}
 @PostMapping("/{id}/comments")public Object comment(@PathVariable String kind,@PathVariable long id,@RequestBody Map<String,Object> body){row(kind,id,false);String value=text(body.get("content"),10000);if(value.isBlank())throw new IllegalArgumentException("Write a comment");access.jdbc.update("INSERT INTO workspace_file_comments(file_id,user_id,content) VALUES(?,?,?)",id,access.actor().getId(),value);return comments(kind,id);}
}
